-- The table SEG-10 needs and Phase 2 deliberately did not create
-- (02-02-SUMMARY.md): Phase 2 shipped only the static `agent_action_catalog`
-- (three seeded rows) and the `audit_log` shell; the engine, the queue and
-- the UI were all explicitly deferred to Phase 4. Hand-authored — the RLS
-- half cannot be generated by `drizzle-kit generate`, and mixing generated
-- and hand-written halves has already caused journal drift in this repo
-- (same reason 0001/0006/0013/0014/0015 give in their own headers).
--
-- `risk_level` is a SNAPSHOT copied at proposal time, not a live join to
-- `agent_action_catalog.risk_level` — a later re-classification of an action
-- type must not rewrite the meaning of history already sitting in the queue.
--
-- LD-09 (locked decision): high-risk actions are NOT executed by a suspended
-- Inngest function waiting on an event. The turn that proposes them finishes
-- immediately, and a separate function (plan 04-09) executes the action when
-- a human decides. That is why this table carries everything needed to
-- replay the tool call later — `tool_name`, `tool_input`, `client_id`,
-- `conversation_phone_number`, `channel` — not just a reference to a live
-- run that may no longer exist by the time a human responds.
--
-- LD-04 (locked decision, do not revisit): the two human-facing policies
-- below get NO `client_contact` branch at all — a client contact must never
-- learn that an action about them is awaiting internal approval. This is the
-- same deliberate divergence 0014's header documents for `audit_log`; a
-- `client_contact` scope simply matches neither OR branch and reads zero
-- rows. Do not "fix" this for consistency with `clients` (0007) — that would
-- reintroduce the exact leak this table exists to avoid.
--
-- LD-03 (locked decision, do not revisit): `client_id IS NULL` rows
-- (agency-internal actions) are visible to every team member, admin and
-- member alike, inside the member branch below — same product default as
-- `audit_log`/`messages` (0014/0015).
--
-- Mandatory GUC rule (0002/0007): every uuid GUC comparison below uses
-- `NULLIF(current_setting('app.xxx', true), '')::uuid`, never a bare
-- `::uuid` cast — a pooled connection reused across requests returns `''`,
-- not `NULL`, for a transaction-local GUC after its first use on that
-- physical backend, and `''::uuid` throws instead of failing closed.

CREATE TABLE "approval_queue" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"agency_id" text NOT NULL,
	"client_id" uuid,
	"action_type_code" text NOT NULL,
	"risk_level" text NOT NULL,
	"tool_name" text NOT NULL,
	"tool_use_id" text NOT NULL,
	"tool_input" jsonb NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"summary" text NOT NULL,
	"requested_by_identity_type" text NOT NULL,
	"requested_by_identity_id" uuid,
	"channel" text DEFAULT 'whatsapp' NOT NULL,
	"conversation_phone_number" text,
	"decided_by_team_member_id" uuid,
	"decided_at" timestamp with time zone,
	"execution_result" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "approval_queue_risk_level_check" CHECK ("approval_queue"."risk_level" in ('low', 'high')),
	CONSTRAINT "approval_queue_status_check" CHECK ("approval_queue"."status" in ('pending', 'approved', 'rejected', 'executed', 'failed')),
	CONSTRAINT "approval_queue_requested_by_identity_type_check" CHECK ("approval_queue"."requested_by_identity_type" in ('team_member', 'client_contact', 'unknown')),
	CONSTRAINT "approval_queue_channel_check" CHECK ("approval_queue"."channel" in ('whatsapp', 'web'))
);
