-- === GRANTs ===
-- GRANT and RLS are independent layers (0001_rls_policies.sql lines 54-56).
-- No DELETE grant: a decided item is history, and agency deletion removes
-- rows via the FK cascade, which is not subject to RLS — same reasoning as
-- 0013's `messages` GRANT.

GRANT SELECT, INSERT, UPDATE ON approval_queue TO app_user;
--> statement-breakpoint

ALTER TABLE approval_queue ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE approval_queue FORCE ROW LEVEL SECURITY;
--> statement-breakpoint

-- The system actor: the agent proposing a high-risk action, and later plan
-- 04-09's replay function reading/updating the row. FOR ALL so that
-- INSERT ... RETURNING and UPDATE ... WHERE both work: Postgres applies
-- SELECT policies to a RETURNING clause and to an UPDATE's row lookup, so a
-- write-only policy would silently break the idempotency gate (which reads
-- back the inserted id) and the replay function's own status update. Same
-- rationale 0013 gives for messages_system_webhook_all.
CREATE POLICY approval_queue_system_all ON approval_queue
  FOR ALL
  USING (
    agency_id = current_setting('app.agency_id', true)
    AND coalesce(current_setting('app.actor', true), '') = 'system_webhook'
  )
  WITH CHECK (
    agency_id = current_setting('app.agency_id', true)
    AND coalesce(current_setting('app.actor', true), '') = 'system_webhook'
  );
--> statement-breakpoint

-- Human read policy (LD-04, see header). Admin sees everything; member sees
-- team-internal (client_id IS NULL) rows plus their assigned clients via
-- client_assignments. Any other scope matches neither branch and reads zero
-- rows.
CREATE POLICY approval_queue_select_by_role ON approval_queue
  FOR SELECT
  USING (
    agency_id = current_setting('app.agency_id', true)
    AND (
      coalesce(current_setting('app.role', true), '') = 'admin'
      OR (
        coalesce(current_setting('app.role', true), '') = 'member'
        AND (
          client_id IS NULL
          OR client_id IN (
            SELECT client_id FROM client_assignments
            WHERE team_member_id = NULLIF(current_setting('app.team_member_id', true), '')::uuid
          )
        )
      )
    )
  );
--> statement-breakpoint

-- Human decision policy — the exact same visibility predicate as the SELECT
-- policy above, UPDATE only, so visibility and decision rights cannot drift
-- apart (T-04-12). RLS cannot restrict WHICH columns change, so the Server
-- Action in plan 04-09 is what constrains the update to
-- status/decided_by_team_member_id/decided_at and to rows currently
-- status = 'pending' (T-04-13). RLS's job here is only "may this human see
-- and touch this row at all".
CREATE POLICY approval_queue_decide_by_role ON approval_queue
  FOR UPDATE
  USING (
    agency_id = current_setting('app.agency_id', true)
    AND (
      coalesce(current_setting('app.role', true), '') = 'admin'
      OR (
        coalesce(current_setting('app.role', true), '') = 'member'
        AND (
          client_id IS NULL
          OR client_id IN (
            SELECT client_id FROM client_assignments
            WHERE team_member_id = NULLIF(current_setting('app.team_member_id', true), '')::uuid
          )
        )
      )
    )
  )
  WITH CHECK (
    agency_id = current_setting('app.agency_id', true)
    AND (
      coalesce(current_setting('app.role', true), '') = 'admin'
      OR (
        coalesce(current_setting('app.role', true), '') = 'member'
        AND (
          client_id IS NULL
          OR client_id IN (
            SELECT client_id FROM client_assignments
            WHERE team_member_id = NULLIF(current_setting('app.team_member_id', true), '')::uuid
          )
        )
      )
    )
  );
